/* Member, public, and relationship flows. All external delivery is simulated. */
'use strict';
AC.renders.profile=()=>{const p=AC.byId(AC.params.get('id'));const connected=p.id==='p9';return `${AC.title('','',AC.link('search',AC.icon('back')+' Back to search','btn quiet'),'Discover / Alumni profile')}<section class="profile-heading" style="margin-bottom:32px">${AC.avatar(p,'large')}<div class="identity">${AC.badge(p)}<h1>${p.name}</h1><p>${p.title} · ${p.company}</p><p class="small muted" style="margin-top:8px">${AC.icon('pin')} ${p.metro} <span style="padding:0 8px">·</span> Wisconsin ’${String(p.year).slice(-2)}</p></div><div class="od-cluster">${AC.btn(AC.icon(AC.state.saved.includes(p.id)?'check':'save')+' '+(AC.state.saved.includes(p.id)?'Saved':'Save contact'),'save','',`data-id="${p.id}" data-text="true" aria-pressed="${AC.state.saved.includes(p.id)}"`)}${AC.link('outreach',AC.icon('mail')+' Reach out','btn primary','?id='+p.id)}</div></section><div class="split"><div class="stack"><section class="panel pad"><div class="section-head"><h2>At a glance</h2><span class="chip ai">AI-generated summary</span></div><ul style="padding-left:20px;color:var(--fg-2);margin-bottom:0"><li>${p.title==='Role not provided'?'A Wisconsin graduate based in '+p.city+'.':p.title+' at '+p.company+', working in '+p.specialty.toLowerCase()+'.'}</li><li>${p.confirmed?'Profile details confirmed by '+p.name.split(' ')[0]+'. '+(p.open.length?'Open to '+p.open.slice(0,2).join(' and ').toLowerCase()+'.':''): 'Professional details are drawn from public and licensed sources and have not yet been confirmed.'}</li></ul><p class="meta" style="margin-top:16px">AI can miss context. Review the experience and source details below.</p></section><section class="panel pad"><h2 style="margin-bottom:24px">Experience & education</h2><div class="timeline"><div class="timeline-item"><span class="timeline-dot"></span><div><h3>${p.title}</h3><p>${p.company} · Current</p><p>${p.specialty}</p></div></div><div class="timeline-item"><span class="timeline-dot"></span><div><h3>Previous experience</h3><p>${p.history}</p></div></div><div class="timeline-item"><span class="timeline-dot"></span><div><h3>University of Wisconsin–Madison</h3><p>${p.school}</p><p>${p.degree} · Class of ${p.year}</p></div></div></div></section><section class="panel pad"><div class="section-head"><h2>Open to connecting</h2></div>${p.open.length?`<div class="od-cluster">${p.open.map(t=>`<span class="chip">${t}</span>`).join('')}</div>`:'<p class="small muted">Preferences haven’t been shared yet. You can still send a respectful invitation through the email relay.</p>'}</section><section class="panel pad"><div class="section-head"><h2>Your private notes</h2><span class="chip">${AC.icon('lock')}Only you</span></div>${AC.textarea('Notes about '+p.name,'private-note',AC.state.notes[p.id]||'','These notes are never shown to this person or other members.')}<div class="form-actions">${AC.btn('Save note','save-note','primary',`data-id="${p.id}"`)}</div></section></div><aside class="right-rail stack"><section class="panel pad"><h2 class="rail-title">A warmer introduction</h2>${p.path?`<div class="od-row"><span class="avatar small">${p.path.split(' ').map(n=>n[0]).join('')}</span><div class="od-field"><strong class="small">${p.path}</strong><span class="meta">${p.confirmed?'A mutual connection':'A possible connection · ask first'}</span></div></div><p class="small muted" style="margin:16px 0">Ask ${p.path.split(' ')[0]} to introduce you. Both people choose whether to proceed.</p>${AC.link('introductions','Request introduction','btn','?id='+p.id)}`:`<p class="small muted">No shared connection is currently recorded. Start with a brief, thoughtful message.</p>`}</section><section class="panel pad"><h2 class="rail-title">Contact details</h2><p class="meta" style="margin-bottom:20px">Visible according to ${p.name.split(' ')[0]}’s settings. Your email stays hidden until they reply.</p><div class="detail-list"><div class="detail-row"><span class="eyebrow">Email</span>${p.confirmed?`<a class="small" href="${AC.url('outreach','?id='+p.id)}">Send through private relay ${AC.icon('arrow')}</a><span class="meta">Address available to verified members · Use relay for first contact</span><details><summary>View email address</summary><p>${p.email}</p><span class="chip success">${AC.icon('check')}Email verified</span></details>`:`<span class="small">${AC.icon('lock')} Not shared by the member</span><span class="meta">This unclaimed profile has no member-approved email visibility. Use the private relay.</span>`}</div><div class="detail-row"><span class="eyebrow">Phone</span><span class="small">${connected?p.phone:AC.icon('lock')+' Connections only'}</span><span class="meta">${connected?'Visible because you’re connected. Phone not independently verified.':'A phone number is shared only after a connection is accepted.'}</span></div><div class="detail-row"><span class="eyebrow">Website</span><span class="small">${p.confirmed?'https://'+p.company.toLowerCase().replace(/[^a-z]/g,'')+'.example.com':'Not provided'}</span><span class="meta">${p.confirmed?'Visible to verified members · Member-provided':'No website has been shared'}</span></div><div class="detail-row"><span class="eyebrow">LinkedIn</span><span class="small">${AC.icon('lock')} Hidden</span><span class="meta">${p.name.split(' ')[0]} hasn’t made this detail available.</span></div></div><div class="form-actions">${AC.btn('Where did this data come from?','sources','quiet',`data-id="${p.id}"`)}</div></section><p class="footnote">${p.confirmed?'Confirmed: claimed and verified by this person.':'Unconfirmed is a normal profile state. The person has not yet claimed it.'}</p></aside></div>`};
AC.handlers['save-note']=b=>{AC.state.notes[b.dataset.id]=document.getElementById('private-note').value;AC.persist();AC.toast('Private note saved. Only you can see it.')};
AC.handlers.sources=b=>{let p=AC.byId(b.dataset.id);AC.modal('About this profile’s data',`<p class="small muted">Each field has a source. This fictional prototype illustrates the disclosure, without asserting real records.</p><div class="detail-list"><div class="detail-row"><strong>Name & education</strong><span class="small">${p.confirmed?'Confirmed by member':'Alumni roster (sample)'}</span></div><div class="detail-row"><strong>Current role & experience</strong><span class="small">${p.confirmed?'Member-provided':'Licensed professional data / public web (sample)'}</span></div><div class="detail-row"><strong>Contact details & visibility</strong><span class="small">${p.confirmed?'Member-controlled; verification is labeled per field':'No member-approved contact preferences yet'}</span></div><div class="detail-row"><strong>Summary & relevance</strong><span class="small">AI-generated from profile fields; not independently verified</span></div></div><div class="form-actions">${AC.btn('Close','close-dialog','primary')}</div>`,b)};
AC.renders['sign-in']=()=>`<main class="auth-shell"><section class="auth-story">${AC.brand()}<div><div class="eyebrow accent" style="margin-bottom:24px">Your alumni network, nationwide.</div><h1>A shared beginning.<br><span class="accent">A world of possibility.</span></h1><p class="muted" style="max-width:40ch;margin-top:24px">Build professional relationships with people who share your Wisconsin story.</p></div><p class="small muted story-foot">Private by design. Open only to verified UW–Madison alumni.</p></section><section class="auth-form"><div id="auth-content"><div class="eyebrow accent" style="margin-bottom:16px">Welcome back</div><h1>Your next connection starts here.</h1><p>Sign in with your email. We’ll send a secure link—no password needed.</p>${AC.field('Email address','signin-email','','email','Use the address associated with your alumni profile.','autocomplete="email" required')}<div class="form-actions">${AC.btn('Send sign-in link '+AC.icon('arrow'),'send-link','primary')}</div><p class="meta">Prototype only. No email is sent.</p></div><div class="auth-footer">${AC.icon('lock')} Profiles are private and are never indexed by search engines.<br><br>${AC.link('claim','Is this your profile?','small')} <span style="padding:0 8px">·</span> ${AC.link('remove','Remove my profile','small')}</div></section></main>`;
AC.handlers['send-link']=b=>{let email=document.getElementById('signin-email'),error=document.getElementById('signin-email-error');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)){error.hidden=false;error.textContent='Enter a complete email address, such as alex@example.com.';email.setAttribute('aria-invalid','true');email.focus();return}error.hidden=true;email.removeAttribute('aria-invalid');b.disabled=true;b.textContent='Preparing your link…';setTimeout(()=>{document.getElementById('auth-content').innerHTML=`<span class="chip success">${AC.icon('mail')}Sign-in link ready</span><h1 style="margin-top:24px">Check your inbox.</h1><p>A real sign-in link would be sent to <strong>${AC.esc(email.value)}</strong>. It would expire after a short period.</p>${AC.notice('This prototype simulates authentication. Choose a sample account state below.')}<div class="form-actions">${AC.link('index','Continue as verified member','btn primary')}${AC.link('verification-pending','Continue as pending member','btn')}</div><div class="form-actions">${AC.btn('Use a different email','reset-signin','quiet')}</div>`},650)};
AC.handlers['reset-signin']=()=>AC.render();
AC.renders['verification-pending']=()=>`<header class="public-header">${AC.brand()}${AC.link('sign-in','Sign out','btn quiet')}</header><main class="public-main"><div class="eyebrow accent" style="margin-bottom:16px">One more step</div><h1>You’re signed in.<br>Let’s verify your Wisconsin connection.</h1><p>Profiles and contact details become available after your alumni status is verified.</p><section class="panel pad"><div class="od-cluster" style="margin-bottom:24px"><span class="chip">${AC.icon('clock')}Verification pending</span><span class="small muted">alex.morgan@example.com</span></div><div id="verification-status">${AC.notice('We couldn’t automatically match your email to an alumni record. Share your graduation details for a manual review.')}</div><div class="form-grid" style="margin-top:24px">${AC.field('Full name','verify-name','Alex Morgan')}${AC.field('Class year','verify-year','2008','number')}${AC.field('School or college','verify-school','Wisconsin School of Business')}${AC.field('Degree / major','verify-degree','BBA, Finance')}</div><div class="form-actions">${AC.btn('Request verification','request-verification','primary')}</div><p class="meta" style="margin-top:16px">We’ll use these details only to verify your alumni status. No profile access while pending.</p></section><p class="small muted" style="margin-top:24px">Need help? alumni-support@example.com</p></main>`;
AC.handlers['request-verification']=b=>{if(!document.getElementById('verify-name').value.trim()||!/^(19|20)\d{2}$/.test(document.getElementById('verify-year').value)){AC.toast('Add your full name and a four-digit class year.');return}AC.state.verificationRequested=true;AC.persist();document.getElementById('verification-status').innerHTML=AC.notice('Verification request received in this prototype. You’ll keep this pending state until an administrator reviews it.','success');b.disabled=true;b.textContent='Request submitted'};
AC.renders.claim=()=>`<header class="public-header">${AC.brand()}${AC.link('sign-in','Already a member? Sign in','btn quiet')}</header><main class="public-main"><div class="eyebrow accent" style="margin-bottom:16px">Your profile. Your choice.</div><h1>Is this you?</h1><p>Claim your alumni profile to confirm its details, choose what to share, and connect with other Wisconsin alumni.</p><section class="panel pad"><div class="od-row"><span class="avatar">AM</span><div><h2>Alex Morgan</h2><p class="small muted">University of Wisconsin–Madison · Class of 2008</p></div></div><p class="small muted" style="margin-top:24px">This private link shows only enough information to identify your record. Professional and contact details are available only inside the verified network.</p><div class="divider"></div><div id="claim-status">${AC.field('Your email address','claim-email','','email','We’ll verify your identity before giving access to this profile.')}<div class="form-actions">${AC.btn('Claim my profile','claim-profile','primary')}</div></div></section><section style="margin-top:32px"><h2>Prefer not to be included?</h2><p class="small muted" style="margin:12px 0">You can remove your profile without creating an account. We’ll retain a minimal suppression record so it won’t be re-added.</p>${AC.link('remove','Remove my profile '+AC.icon('arrow'),'btn quiet')}</section><p class="footnote">Illustrative private claim link · No public directory or profile search.</p></main>`;
AC.handlers['claim-profile']=()=>{let el=document.getElementById('claim-email');if(!el.checkValidity()||!el.value){el.reportValidity();return}document.getElementById('claim-status').innerHTML=AC.notice('Claim request started. In the live service, check your email to verify your identity. No email has been sent by this prototype.','success')+`<div class="form-actions">${AC.link('verification-pending','View verification step','btn primary')}</div>`};
AC.renders.remove=()=>`<header class="public-header">${AC.brand()}${AC.link('sign-in','Sign in','btn quiet')}</header><main class="public-main"><div class="eyebrow accent" style="margin-bottom:16px">No account required</div><h1>Remove your profile.</h1><p>You control whether you’re part of this network.</p><section class="panel pad" id="removal-content">${AC.state.publicRemoved?AC.notice('Your profile has been removed from this prototype. A suppression record prevents it from being re-added.','success'):`<h2>Alex Morgan · Class of 2008</h2><p class="small muted" style="margin-top:16px">Removing this record hides it from member search and introductions. It won’t be re-added by future roster imports.</p><p class="small muted" style="margin-top:16px">A minimal suppression record is kept only to honor your request. Your private removal link identifies this record; no sign-in is needed.</p><div class="form-actions">${AC.btn('Remove my profile now','public-remove','danger')}</div>`}</section><p class="footnote">This prototype changes sample data only. Production removal must also clear indexes, caches, and derived records.</p></main>`;
AC.handlers['public-remove']=()=>{AC.state.publicRemoved=true;AC.addAudit('Public profile removal recorded; suppression enabled');document.getElementById('removal-content').innerHTML=AC.notice('Your profile has been removed. We’ll keep a minimal suppression record so it won’t be re-added. No account was created.','success')};
AC.renders['edit-profile']=()=>{let p=AC.state.profile;return `${AC.title('Make it yours.','Keep your professional story accurate. You decide which contact details to share.','','Profile & privacy / Edit profile')}<div class="tabs">${AC.link('edit-profile','Edit profile','','')}${AC.link('settings','Privacy & visibility','','')}${AC.link('data-sources','Data sources','','')}</div><div class="narrow panel pad">${AC.notice('Your profile is confirmed. Saving an edit doesn’t change the privacy of your contact details.')}<div class="form-grid" style="margin-top:24px">${AC.field('Full name','own-name',p.name)}${AC.field('Current title','own-title',p.title)}${AC.field('Employer','own-company',p.company)}${AC.field('City and state','own-city',p.city)}${AC.field('UW–Madison class year','own-year',p.year,'number')}${AC.select('Industry','own-industry',AC.sectors,p.industry||'Professional services')}${AC.field('School or college','own-school',p.school||'Wisconsin School of Business')}${AC.field('Degree and major','own-degree',p.degree||'BBA, Finance')}</div><fieldset style="margin-top:24px"><legend>Open to</legend><div class="form-grid" style="margin-top:12px">${AC.openTags.map(t=>`<label class="checkbox"><input type="checkbox" name="own-open" value="${t}" ${(p.open||['Networking','Mentoring']).includes(t)?'checked':''}>${t}</label>`).join('')}</div></fieldset><div style="margin-top:24px">${AC.textarea('Professional introduction','own-bio',p.bio||'I help growing businesses build thoughtful, lasting partnerships. Always happy to connect with fellow Wisconsin alumni.','Your own words. AI summaries are labeled separately.')}</div><div class="form-actions">${AC.btn('Save profile','save-own','primary')}${AC.link('settings','Manage contact visibility','btn')}</div><p id="profile-save-error" class="error-text" hidden></p></div>`};
AC.handlers['save-own']=()=>{let name=document.getElementById('own-name').value.trim(),year=document.getElementById('own-year').value;let error=document.getElementById('profile-save-error');if(!name||!/^(19|20)\d{2}$/.test(year)){error.hidden=false;error.textContent='Enter your name and a four-digit class year before saving.';return}error.hidden=true;AC.state.profile={name,title:document.getElementById('own-title').value,company:document.getElementById('own-company').value,city:document.getElementById('own-city').value,year,industry:document.getElementById('own-industry').value,school:document.getElementById('own-school').value,degree:document.getElementById('own-degree').value,open:[...document.querySelectorAll('[name=own-open]:checked')].map(el=>el.value),bio:document.getElementById('own-bio').value};AC.persist();AC.render();document.querySelector('[data-action=save-own]').focus();AC.toast('Profile updated. Contact visibility is unchanged.')};
AC.renders.settings=()=>`${AC.title('Your privacy, in plain sight.','Choose who can see each contact detail. You can change these settings at any time.','','Profile & privacy')}<div class="tabs">${AC.link('edit-profile','Edit profile','')}${AC.link('settings','Privacy & visibility','')}${AC.link('data-sources','Data sources','')}</div><div class="split"><section class="panel pad"><h2>Contact visibility</h2><p class="small muted" style="margin:12px 0 24px">“Verified members” means alumni who have completed verification. “Connections” means people whose connection you’ve accepted.</p><div class="stack">${[['email','Email address',AC.state.contacts?.email||'alex.morgan@example.com',AC.state.contactVerified?.email!==false],['phone','Phone number',AC.state.contacts?.phone??'312-555-0100',false],['website','Website',AC.state.contacts?.website??'https://northfield.example.com',false],['linkedin','LinkedIn',AC.state.contacts?.linkedin||'',false]].map(([key,label,value,verified])=>`<div class="detail-row"><div class="od-row"><strong class="small">${label}</strong>${verified?'<span class="chip success">Verified</span>':''}</div><label class="sr-only" for="contact-${key}">${label}</label><input id="contact-${key}" value="${AC.esc(value)}" placeholder="Not provided" aria-label="${label}"><label class="sr-only" for="privacy-${key}">${label} visibility</label><select id="privacy-${key}">${[['members','All verified members'],['connections','Connections only'],['hidden','Hidden from everyone']].map(([v,t])=>`<option value="${v}" ${AC.state.privacy[key]===v?'selected':''}>${t}</option>`).join('')}</select><span class="meta" id="privacy-help-${key}">${AC.visibilityCopy(AC.state.privacy[key])}</span></div>`).join('')}</div><div class="form-actions">${AC.btn('Save privacy settings','save-privacy','primary')}</div></section><aside class="right-rail stack"><section class="panel pad"><h2 class="rail-title">Private from the start</h2><div class="rail-list"><div class="od-row-top">${AC.icon('lock')}<p class="small muted">Your profile is never public or indexed by search engines.</p></div><div class="od-row-top">${AC.icon('mail')}<p class="small muted">First-contact outreach uses a relay. Your sender address stays private until the recipient replies.</p></div><div class="od-row-top">${AC.icon('intro')}<p class="small muted">Introductions require agreement from the connector and the recipient.</p></div></div></section><section class="panel pad"><h3>Leave the network</h3><p class="small muted" style="margin:12px 0">Removal needs no account or explanation, and prevents future re-import.</p>${AC.link('remove','Remove my profile','btn danger')}</section></aside></div>`;
AC.visibilityCopy=v=>v==='members'?'Visible to every verified alumni member.':v==='connections'?'Hidden until you have accepted a connection.':'Hidden from all other members.';
AC.handlers['save-privacy']=()=>{let email=document.getElementById('contact-email').value.trim(),phone=document.getElementById('contact-phone').value.trim();if(email&&!/^[^\s@]+@example\.com$/i.test(email)){AC.toast('Use a fictional example.com email in this prototype.');document.getElementById('contact-email').focus();return}if(phone&&!/555-01\d{2}/.test(phone)){AC.toast('Use a fictional phone number in the 555-01xx range.');document.getElementById('contact-phone').focus();return}let previous=AC.state.contacts?.email||'alex.morgan@example.com';AC.state.contacts||={};Object.keys(AC.state.privacy).forEach(key=>{AC.state.privacy[key]=document.getElementById('privacy-'+key).value;AC.state.contacts[key]=document.getElementById('contact-'+key).value.trim()});if(previous!==email){AC.state.contactVerified||={};AC.state.contactVerified.email=false}AC.persist();AC.render();document.querySelector('[data-action=save-privacy]').focus();AC.toast('Contact details and privacy saved. Changed email addresses require verification.')};
AC.renders['data-sources']=()=>`${AC.title('Know where your data comes from.','Review the origin of your profile details and correct anything that needs attention.','','Profile & privacy / Data sources')}<div class="tabs">${AC.link('edit-profile','Edit profile','')}${AC.link('settings','Privacy & visibility','')}${AC.link('data-sources','Data sources','')}</div><section class="panel"><div class="pad">${AC.notice('These are illustrative source records. The live app should retain provider, source date, last review, and correction history per field.')}</div><div class="table-wrap"><table class="responsive"><thead><tr><th>Profile detail</th><th>Current source</th><th>Control</th></tr></thead><tbody>${[['Name','Member-provided'],['Education & class year','Alumni roster, confirmed by member'],['Current employer & title','Member-provided'],['Past positions','Licensed data, confirmed by member'],['Email & phone visibility','Member-provided'],['Summary','AI-generated from your profile']].map(([a,b])=>`<tr><td><strong>${a}</strong></td><td data-label="Source">${b}</td><td>${AC.link('edit-profile','Review / correct','btn quiet')}</td></tr>`).join('')}</tbody></table></div></section>`;
AC.renders.recommendations=()=>`${AC.title('The right connection depends on your goal.','Every suggestion explains its relevance. Change your goal to see a different starting point.','','Discover / Who to meet')}<section class="panel pad" style="margin-bottom:24px"><div class="form-grid">${AC.select('What are you working toward?','recommend-goal',['Build business partnerships','Find clients and referrals','Meet investors','Find a mentor'],AC.state.recommendGoal||'Build business partnerships')}${AC.select('Preferred market','recommend-city',['Any market','Chicago','Dallas','Austin','New York'],AC.state.recommendCity||'Any market')}</div><div class="form-actions">${AC.btn('Update recommendations','rank','primary')}<span class="chip ai">AI-assisted · Explainable suggestions</span></div></section><div id="recommend-list"></div><p class="footnote">Recommendations use the selected goal, profile fields, and recorded connection paths. They are suggestions, not endorsements or a global ranking.</p>`;
AC.rank=()=>{let goal=document.getElementById('recommend-goal').value,city=document.getElementById('recommend-city').value;AC.state.recommendGoal=goal;AC.state.recommendCity=city;AC.persist();let key=goal.includes('investors')?'capital':goal.includes('clients')?'clients':goal.includes('mentor')?'mentor':'partners';let people=AC.visiblePeople().filter(p=>(city==='Any market'||p.city===city)&&(key!=='mentor'||p.open.includes('Mentoring'))).sort((a,b)=>(b.goal===key)-(a.goal===key));document.getElementById('recommend-list').innerHTML=AC.stateBlock(people.length?`<div class="stack">${people.map(p=>`<section class="panel">${AC.person(p)}<div class="pad" style="border-top:1px solid var(--border-soft)"><span class="chip ai">AI-generated relevance</span><p class="small" style="margin-top:12px">${p.why}</p><p class="meta" style="margin-top:8px">Goal: ${goal.toLowerCase()} · Evidence: ${p.specialty}, ${p.city}${p.path?', possible path via '+p.path:''}</p></div></section>`).join('')}</div>`:AC.empty('No recommendations for this market','Choose a different market or a broader goal.',AC.btn('Broaden market','broaden-recommend','primary')))};
AC.handlers.rank=AC.rank;AC.handlers['broaden-recommend']=()=>{document.getElementById('recommend-city').selectedIndex=0;AC.params.delete('state');AC.rank()};
AC.renders.relationships=()=>`${AC.title('Relationships worth keeping.','A place for the people you know—and the conversations you want to continue.',AC.link('search','Find alumni '+AC.icon('arrow'),'btn primary'),'Relationships')}${AC.relationshipTabs()}<div class="split"><div class="stack"><section class="panel"><div class="summary-strip"><div class="od-stat"><strong>${AC.state.saved.length}</strong><span>Saved contacts</span></div><div class="od-stat"><strong>${AC.state.interactions.length}</strong><span>Logged interactions</span></div><div class="od-stat"><strong>${AC.state.followups.filter(f=>!f.done).length}</strong><span>Open follow-ups</span></div></div><div class="pad"><div class="section-head"><h2>Your saved contacts</h2>${AC.link('saved','View all','btn quiet')}</div></div>${AC.stateBlock(AC.state.saved.length?AC.personList(AC.state.saved.map(AC.byId)):AC.empty('Start with one connection','Save an alumnus from discovery to keep their profile here.',AC.link('search','Find alumni','btn primary')),'No relationships saved yet','A meaningful network starts with a single conversation.',AC.link('search','Find alumni','btn primary'))}</section><section class="panel pad"><div class="section-head"><h2>Interaction log</h2>${AC.btn(AC.icon('plus')+' Log interaction','log-interaction')}</div>${AC.state.interactions.length?`<div class="timeline">${AC.state.interactions.map(i=>`<div class="timeline-item"><span class="timeline-dot"></span><div><h3>${AC.esc(i.person)} · ${AC.esc(i.type)}</h3><p>${AC.esc(i.note)}</p><p class="meta">${AC.esc(i.date)} · Private to you</p></div></div>`).join('')}</div>`:'<p class="small muted">No interactions logged yet. Record a conversation to remember the details that matter.</p>'}</section></div><aside class="right-rail stack"><section class="trip-callout"><div class="eyebrow">The next conversation</div><h2>Follow through.<br>Stay connected.</h2><p>Set a reminder while a conversation is still fresh.</p>${AC.link('followups','Manage follow-ups '+AC.icon('arrow'),'btn primary')}</section><section class="panel pad"><h2 class="rail-title">Keep it personal</h2><p class="small muted">Notes, lists, and interaction history are private to you. They never become another member’s profile data.</p></section></aside></div>`;
AC.renders.saved=()=>`${AC.title('People you want to stay close to.','Saved contacts are private. Saving someone doesn’t notify them.','','Relationships / Saved contacts')}${AC.relationshipTabs()}<div class="field" style="max-width:480px;margin-bottom:24px"><label for="saved-search">Find a saved contact</label><input id="saved-search" placeholder="Search name, company, or city"></div><section class="panel" id="saved-list">${AC.savedList()}</section>`;
AC.savedList=()=>{let q=document.getElementById('saved-search')?.value.toLowerCase()||'';let people=AC.state.saved.map(AC.byId).filter(p=>(p.name+' '+p.company+' '+p.city).toLowerCase().includes(q));return AC.stateBlock(people.length?AC.personList(people):AC.empty(q?'No saved contacts match':'No saved contacts yet',q?'Try another name or clear the search.':'Save someone from discovery to find them here.',AC.link('search','Find alumni','btn primary')),'No saved contacts yet','Save an alumnus to start building your relationships.',AC.link('search','Find alumni','btn primary'))};
AC.renders.lists=()=>`${AC.title('Give your network a little structure.','Organize contacts around a market, a project, or the next conversation.',AC.btn(AC.icon('plus')+' New list','new-list','primary'),'Relationships / Lists')}${AC.relationshipTabs()}<div id="relationship-lists" class="stack">${AC.stateBlock(AC.state.lists.length?AC.state.lists.map((l,i)=>`<section class="panel pad"><div class="section-head"><div><h2>${AC.esc(l)}</h2><p class="small muted">${(AC.state.listMembers?.[l]||[]).length} contacts · Private to you</p></div>${AC.btn('Manage contacts','manage-list','',`data-index="${i}"`)}</div><div class="od-cluster">${(AC.state.listMembers?.[l]||[]).map(id=>AC.link('profile',AC.byId(id).name,'chip','?id='+id)).join('')||'<p class="small muted">Add a saved contact to start this list.</p>'}</div></section>`).join(''):AC.empty('A place for your next project','Create a list, then add the people you want to keep together.',AC.btn('Create a list','new-list','primary')))}</div>`;
AC.handlers['new-list']=b=>AC.modal('Create a private list',`${AC.field('List name','list-name','','text','For example, “Dallas introductions”.','maxlength="80"')}<div class="form-actions">${AC.btn('Create list','create-list','primary')}</div>`,b);
AC.handlers['create-list']=()=>{let name=document.getElementById('list-name').value.trim();if(!name){AC.toast('Give your list a name.');return}if(AC.state.lists.includes(name)){AC.toast('A list with this name already exists.');return}AC.state.lists.push(name);AC.persist();AC.close();AC.render();AC.toast('Private list created')};
AC.handlers['manage-list']=b=>{let name=AC.state.lists[Number(b.dataset.index)],ids=AC.state.listMembers?.[name]||[];AC.modal('Contacts in '+AC.esc(name),AC.state.saved.length?`<fieldset><legend>Choose saved contacts</legend>${AC.state.saved.map(id=>`<label class="checkbox"><input name="list-contact" type="checkbox" value="${id}" ${ids.includes(id)?'checked':''}>${AC.byId(id).name}</label>`).join('')}</fieldset><div class="form-actions">${AC.btn('Save list','save-list','primary',`data-index="${b.dataset.index}"`)}</div>`:`<p class="muted">Save a contact first, then add them to this list.</p><div class="form-actions">${AC.link('search','Find alumni','btn primary')}</div>`,b)};
AC.handlers['save-list']=b=>{AC.state.listMembers||={};AC.state.listMembers[AC.state.lists[Number(b.dataset.index)]]=[...document.querySelectorAll('[name=list-contact]:checked')].map(i=>i.value);AC.persist();AC.close();AC.render();AC.toast('List updated')};
AC.handlers['log-interaction']=b=>AC.modal('Remember the conversation',`${AC.select('Person','log-person',AC.state.saved.map(id=>AC.byId(id).name),AC.byId(AC.state.saved[0]).name)}<div class="form-grid" style="margin-top:16px">${AC.select('Interaction','log-type',['Coffee','Call','Email','Introduction','Event'])}${AC.field('Date','log-date','2026-11-03','date')}</div><div style="margin-top:16px">${AC.textarea('Private note','log-note','','What would you like to remember?')}</div><div class="form-actions">${AC.btn('Save interaction','save-interaction','primary')}</div>`,b);
AC.handlers['save-interaction']=()=>{let note=document.getElementById('log-note').value.trim(),person=document.getElementById('log-person').value,date=document.getElementById('log-date').value;if(!person||!date||!note){AC.toast('Choose a person, date, and a short note.');return}AC.state.interactions.unshift({person,type:document.getElementById('log-type').value,date,note});AC.persist();AC.close();AC.render();AC.toast('Interaction saved privately')};
AC.renders.followups=()=>`${AC.title('A thoughtful next step.','Keep promises, reconnect, and follow through without turning relationships into a pipeline.',AC.btn(AC.icon('plus')+' Add reminder','new-reminder','primary'),'Relationships / Follow-ups')}${AC.relationshipTabs()}<section class="panel pad">${AC.stateBlock(AC.state.followups.length?`<div class="detail-list">${AC.state.followups.map((f,i)=>`<div class="detail-row"><div class="od-row"><div class="od-fill"><h3>${AC.esc(f.title)}</h3><p class="small muted">${AC.esc(f.person)} · ${f.date}</p><span class="chip ${f.done?'success':''}">${f.done?'Completed':'Reminder set'}</span></div>${AC.btn(f.done?'Reopen':'Mark done','complete-reminder','',`data-index="${i}"`)}</div></div>`).join('')}</div>`:AC.empty('Nothing to follow up on yet','Add a private reminder after a meeting or introduction. Browser notifications are not sent by this prototype.',AC.btn('Add your first reminder','new-reminder','primary')),'You’re all caught up','Add a reminder whenever you want to continue a conversation.',AC.btn('Add reminder','new-reminder','primary'))}</section>`;
AC.handlers['new-reminder']=b=>AC.modal('Add a follow-up',`${AC.field('What would you like to do?','reminder-title','','text','For example, send Elena the partnership overview.')}<div class="form-grid" style="margin-top:16px">${AC.select('Person','reminder-person',AC.state.saved.map(id=>AC.byId(id).name))}${AC.field('Reminder date','reminder-date','2026-11-10','date')}</div><div class="form-actions">${AC.btn('Set reminder','save-reminder','primary')}</div>`,b);
AC.handlers['save-reminder']=()=>{let title=document.getElementById('reminder-title').value.trim(),person=document.getElementById('reminder-person').value,date=document.getElementById('reminder-date').value;if(!title||!person||!date){AC.toast('Add an action, a person, and a reminder date.');return}AC.state.followups.push({title,person,date,done:false});AC.persist();AC.close();AC.render();AC.toast('Reminder saved in your private follow-ups')};
AC.handlers['complete-reminder']=b=>{let f=AC.state.followups[Number(b.dataset.index)];f.done=!f.done;AC.persist();AC.render()};
